' : ''}Harvested ${harvest.messages.length} messages, ${totalBlocks(harvest)} blocks.`); } catch (err) { console.error('[ChatGPT Export v0.3] Harvest failed:', err); alert('Failed to harvest conversation. Check console for details.'); } } function totalBlocks(h) { return (h.messages || []).reduce((n, m) => n + (m.blocks?.length || 0), 0); } /* =========================== Harvest v0.3: schema + logic =========================== */ /** * HarvestV03 = { * meta: { title, url, exported_at, model?, locale? }, * messages: [ * { index, id, role, timestamp?, hash, * plain: { text, md }, * html, blocks: Block[], segments: Segment[] } * ], * pairs?: Array<{ userIndex, assistantIndex }> * } */ async function harvestConversationV03() { const messageEls = selectMessageElements(); const messages = []; let i = 0; for (const el of messageEls) { messages.push(await normalizeMessageV03(el, i++)); } const meta = { title: safeTitle(document.title.replace(/\s*\|\s*ChatGPT.*/i, '') || 'ChatGPT Conversation'), url: location.href, exported_at: new Date().toISOString(), model: detectModel(), locale: document.documentElement.getAttribute('lang') || undefined }; const pairs = buildPairs(messages); return { meta, messages, pairs }; } /* =========================== Message selection & parsing =========================== */ function selectMessageElements() { const selectors = [ '[data-testid="conversation-turn"]', '[data-message-author-role]', 'main article', 'article', 'div[role="article"]' ]; const seen = new Set(); const out = []; for (const sel of selectors) { document.querySelectorAll(sel).forEach(el => { if (seen.has(el)) return; const text = (el.textContent || '').trim(); if (!text) return; seen.add(el); out.push(el); }); } return out; } async function normalizeMessageV03(el, index) { const role = detectRole(el); const id = el.getAttribute('id') || el.dataset.messageId || `msg-${index+1}`; const timestamp = detectTimestamp(el); // 1) Find rich content node & clone it const contentNode = fi