#')); return { index, id, role, timestamp, hash, plain: { text, md: mdText }, html, blocks, segments }; } function findContentNode(el) { return el.querySelector('[data-testid="markdown"], .markdown, .prose, .whitespace-pre-wrap, article, div') || el; } /* =========================== Sanitizer =========================== */ function sanitizeClone(root) { // Remove obvious UI chrome / controls / citations / avatars / toolbars const DROP = [ 'button', '[role="toolbar"]', '[data-testid="webpage-citation-pill"]', '[data-testid="citation-chip"]', '[data-testid="source-chip"]', '[data-testid="inline-toolbar"]', 'svg[aria-hidden="true"]', 'nav', 'aside' ]; root.querySelectorAll(DROP.join(',')).forEach(n => n.remove()); // Strip non-content attributes that might bloat HTML snapshots root.querySelectorAll('[class]').forEach(n => n.removeAttribute('class')); root.querySelectorAll('[style]').forEach(n => n.removeAttribute('style')); // Normalize links: keep href, drop target/rel/onclick root.querySelectorAll('a').forEach(a => { const href = a.getAttribute('href') || ''; [...a.attributes].forEach(attr => { if (!/^(href|title|name|id|data-.*)$/.test(attr.name)) a.removeAttribute(attr.name); }); if (href && !href.startsWith('#')) a.setAttribute('href', href); }); // Remove empty nodes Array.from(root.querySelectorAll('*')).forEach(n => { if (!n.firstChild && !/^(img|br|hr|input|source)$/.test(n.tagName.toLowerCase())) { const text = (n.textContent || '').trim(); if (!text) n.remove(); } }); } /* =========================== Segments (back-compat) =========================== */ function extractSegments(root) { const segments = []; // code root.querySelectorAll('pre code').forEach(code => { segments.push({ type: 'code', language: (code.className || '').match(/language-([a-z0-9+#-]+)/i)?.[1] || '', text: code.innerText }); }); // images root.querySelectorAll('img').forEach(img => { segments.push({ type: 'image', alt: img.getAttribute('alt') || '', src: img.getAttribute('src') || '' })