' : ''; } // Inline-ish markdown converter for paras, list items, etc. function toMarkdownInline(node) { let md = ''; const walker = document.createTreeWalker(node, NodeFilter.SHOW_ELEMENT | NodeFilter.SHOW_TEXT); const stack = []; function open(tag, el) { if (tag === 'EM' || tag === 'I') { md += '*'; stack.push('*'); return; } if (tag === 'STRONG' || tag === 'B') { md += '**'; stack.push('**'); return; } if (tag === 'CODE' && el.parentElement?.tagName !== 'PRE') { md += '`'; stack.push('`'); return; } if (tag === 'A') { md += '['; stack.push({ type:'a', href: el.getAttribute('href') || '' }); return; } if (tag === 'BR') { md += ' 
