').trim(); return md; } function textNode(s) { return document.createTextNode(s); } /* =========================== Role, timestamp, model, hash =========================== */ function detectRole(el) { const attr = el.getAttribute('data-message-author-role') || el.querySelector('[data-message-author-role]')?.getAttribute('data-message-author-role'); if (attr) return attr; const aria = (el.getAttribute('aria-label') || '').toLowerCase(); if (/assistant|gpt/.test(aria)) return 'assistant'; if (/you|user/.test(aria)) return 'user'; const text = el.textContent?.trim().slice(0, 80).toLowerCase() || ''; if (text.startsWith('you:')) return 'user'; return 'assistant'; } function detectTimestamp(el) { const t = el.querySelector('time')?.getAttribute('datetime') || el.querySelector('time')?.getAttribute('title') || el.querySelector('time')?.textContent; if (!t) return null; const iso = new Date(t); return isNaN(iso.getTime()) ? (t || null) : iso.toISOString(); } // Best-effort model sniff (header, menus, tooltips—very heuristic) function detectModel() { const candidates = [ '[data-testid="model-switcher"]', '[aria-label*="model"]', 'header [role="button"][aria-haspopup="menu"]', 'header' ]; for (const sel of candidates) { const el = document.querySelector(sel); const txt = (el?.innerText || el?.getAttribute?.('aria-label') || '').trim(); if (txt && /gpt|o\d|4\.?o|mini|pro|sonnet|flash/i.test(txt)) return txt; } // As a last resort, scan header text const hdr = document.querySelector('header'); if (hdr) { const txt = (hdr.innerText || '').trim(); const m = txt.match(/(GPT[\w.-]+|o\d[\w.-]*)/i); if (m) return m[1]; } return undefined; } function hashString(s) { // djb2-ish let h = 5381; for (let i = 0; i < s.length; i++) h = ((h << 5) + h) + s.charCodeAt(i); return (h >>> 0).toString(16); } /* =========================== Q/A Pairs =========================== */ function buildPairs(messages) { const pairs = []; for (let i = 0; i < messages.length; i++) { if (messages[i].role === 