// meta + messages + blocks (heading/para/list/code/table/image/quote/math/divider) + pairs.
// Keeps a “segments” array for backward-compat. Saves to window.__CGPT_EXPORT.lastHarvest,
// logs to console, and copies JSON to clipboard (from the click gesture).

/* ===========================
   Config & Globals
   =========================== */
const CFG = {
  right: 20,
  bottom: 24,
  minSize: 44,
  zIndex: 2147483000,
  nudgeGap: 12,
  urlGuard: /^https:\/\/(chat\.openai\.com|chatgpt\.com)\//,
  recomputeDebounceMs: 120
