  window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;

function findComposer() {
  const candidates = [
    '[contenteditable="true"][role="textbox"]',
    'textarea',
    '[data-testid="composer"], [data-test="composer"]',
    'div[role="textbox"]'
